typedef unsigned int nlUint32;
typedef unsigned int nslSourceId;

enum nslSoundParamEnum {
  NSL_SOUNDPARAM_VOLUME,
  NSL_SOUNDPARAM_PITCH,
  NSL_SOUNDPARAM_MINDIST,
  NSL_SOUNDPARAM_MAXDIST
};

enum nslSourceTypeEnum {
  NSL_SOURCETYPE_SFX,
  NSL_SOURCETYPE_AMBIENT,
  NSL_SOURCETYPE_MUSIC,
  NSL_SOURCETYPE_VOICE,
  NSL_SOURCETYPE_MOVIE,
  NSL_SOURCETYPE_USER1,
  NSL_SOURCETYPE_USER2
};

struct nslSource {
  bool used;
  bool looping;
  char fileName[48];
  int bank;
  nslSourceId myId;
  float length;
  float paddedLength;
  nslSourceTypeEnum type;
  nlUint32 gasSourceId;
  float rawVolume;
  float pitch;
  float minDist;
  float maxDist;
};

struct nslSystem {
  float listenerPo[4][4];
  nslSource sourceSlots[512];
  char data_to_initialized[0x9810];
  int initialized;
  nlUint32 numBanks;
  char queuedSounds_and_modes[0x28];
  unsigned long long lastClock;
  bool on;
};

extern nslSystem nsl;
void nslFatal(const char *format, ...);
extern const char nsl_not_initialized[];
extern const char source_invalid_id[];
extern const char source_bad_gas_id[];
extern const char source_slot_too_high[];
extern const char source_id_mismatch[];
extern const char source_instance_zero[];
extern const char source_slot_over_total[];

__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nslFatal__FPCce, 0x00391420");
__asm__(".equ nsl_not_initialized, 0x0051BDC8");
__asm__(".equ source_invalid_id, 0x0051BCB0");
__asm__(".equ source_bad_gas_id, 0x0051BCD8");
__asm__(".equ source_slot_too_high, 0x0051BCF8");
__asm__(".equ source_id_mismatch, 0x0051BD28");
__asm__(".equ source_instance_zero, 0x0051BD68");
__asm__(".equ source_slot_over_total, 0x0051BD90");

inline __attribute__((always_inline)) void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal(nsl_not_initialized);
}

inline __attribute__((always_inline)) void _nslCheckSourceIdValidity(nslSourceId checkId)
{
  nslSourceId checkSlot = (checkId & 0x0000FFFF);
  nslSourceId upCheckId = (checkId & 0xFFFF0000);
  nlUint32 gasId = nsl.sourceSlots[checkSlot].gasSourceId;
  nlUint32 negativeOne = (nlUint32)-1;
  if (!(checkId != 0)) nslFatal(source_invalid_id);
  if (!(gasId != negativeOne)) nslFatal(source_bad_gas_id);
  if (!(checkSlot < 512)) nslFatal(source_slot_too_high);
  if (!(checkId == nsl.sourceSlots[checkSlot].myId)) nslFatal(source_id_mismatch);
  if (!(upCheckId > 0)) nslFatal(source_instance_zero);
  if (checkSlot > 512) nslFatal(source_slot_over_total);
  return;
}

#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_SOURCE_ID_VALID(checkId) _nslCheckSourceIdValidity(checkId)
#define NSL_GET_SOURCE_SLOT_FROM_ID(x) (x & 0x0000FFFF)

void nslSetSourceParam( nslSourceId sourceToSet, nslSoundParamEnum whichParam, 
                        float newVal )
{
  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_SOURCE_ID_VALID(sourceToSet);
  switch (whichParam) {
    case NSL_SOUNDPARAM_VOLUME: 
      nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(sourceToSet)].rawVolume=newVal; break;
    case NSL_SOUNDPARAM_PITCH:
      nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(sourceToSet)].pitch=newVal; break;
    case NSL_SOUNDPARAM_MINDIST:
      nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(sourceToSet)].minDist=newVal; break;
    case NSL_SOUNDPARAM_MAXDIST:
      nsl.sourceSlots[NSL_GET_SOURCE_SLOT_FROM_ID(sourceToSet)].maxDist=newVal; break;
    default: nslFatal(false && "Unhandled sourcetype"); break;
  }

}
